ALTER TABLE market_calls ADD COLUMN history_user_id TEXT;
ALTER TABLE market_calls ADD COLUMN history_json TEXT CHECK(history_json IS NULL OR json_valid(history_json));
CREATE INDEX market_history_owner ON market_calls(tenant_id,history_user_id,created_at DESC) WHERE history_user_id IS NOT NULL;
CREATE TABLE experience_settings (task TEXT PRIMARY KEY NOT NULL, options_json TEXT NOT NULL CHECK(json_valid(options_json)), result_json TEXT NOT NULL CHECK(json_valid(result_json)));
INSERT INTO experience_settings VALUES ('text','{"recommendations":[["十年后的信","请以第一人称写一封给十年后自己的信。语气温柔、克制而真诚，回顾此刻正在坚持的事情、害怕失去的东西和仍未说出口的愿望；加入两个具体生活细节，让情绪有落点；结尾不要给出确定答案，而是留下一个开放式悬念。全文约 900 字，避免空泛鸡汤。"],["雨夜故事","请写一则发生在雨夜便利店的短篇故事。设计清晰的开场钩子、人物冲突和一次合理但意外的反转；主要人物不超过三人，用动作和对话推进情节，减少旁白解释；结尾留有余味但不故弄玄虚。全文约 1200 字，现实主义风格。"],["开业推文","请为一家新开的社区手作面包店写开业推文。突出当天现烤、邻里感、可见的手作过程和限时优惠，开头 20 字内抓住注意力；正文包含店铺亮点、三款主推产品、开业活动、地址与营业时间；语气亲切自然，避免夸张营销，给出一个主标题和三个备选标题。"],["咖啡烘焙","请用适合咖啡入门者的方式解释浅烘和深烘咖啡豆的区别。按烘焙程度、酸度、苦味、香气、醇厚度、咖啡因误区和适合冲煮方式逐项对比；用一张简洁表格总结，并分别推荐适合喜欢果香与喜欢浓郁口感的人如何选择。"],["产品翻译","请将下面的中文产品发布邮件翻译成自然、专业的英文。保留原有段落和项目符号，产品名与技术术语不翻译；语气正式但不生硬，适合发送给海外企业客户。翻译后另附一份术语对照表，并标出原文中可能存在歧义、需要确认的表达。\n\n邮件主题：MoMA 智能路由 2.0 正式发布\n\n尊敬的客户：\n\n您好！我们很高兴地宣布，MoMA 智能路由 2.0 将于 2026 年 10 月 8 日正式上线。本次升级进一步优化了多模型调度能力，帮助企业在保障生成质量的同时降低模型调用成本。\n\n本次更新包括：\n- 新增效果优先、成本优先和平衡模式三种路由策略；\n- 支持按请求内容、响应时延和模型可用性自动选择模型；\n- 新增调用链路追踪与成本分析面板；\n- 支持通过现有 API Key 直接调用，无需修改鉴权方式。\n\n现有客户可在 MoMA 控制台免费体验 30 天。若您希望获取产品咨询、迁移建议或专属报价，请回复本邮件联系我们的客户成功团队。\n\n感谢您一直以来对 MoMA 的支持！\n\nMoMA 产品团队"]],"prompts":[{"label":"项目总结报告","prompt":"请帮我撰写一份专业的项目总结报告。报告需包含项目背景与目标、实施范围、关键里程碑、主要成果与量化数据、团队协作情况、遇到的问题及解决方案、经验复盘和下一阶段计划；语言正式、逻辑清晰，使用分级标题和要点列表，适合向管理层汇报。"},{"label":"分析图片信息","prompt":"请全面分析我上传的图片：先概括画面主题与主要内容，再识别人物、物体、场景、文字、数据和关键细节，说明各元素之间的关系；如包含图表，请提取核心指标、趋势与异常；最后给出基于画面证据的结论，并明确标注无法确认的信息。"},{"label":"总结视频内容","prompt":"请总结我上传的视频内容：按时间顺序梳理主要情节或观点，提取关键人物、事件、数据和结论，标注重要时间点；区分事实、观点和推测，并用一段摘要加分点列表呈现，最后给出适合快速阅读的三条核心要点。"}]}','{"answer":"模拟调用已完成。","points":["先明确目标、对象与使用场景，避免回答停留在泛泛描述。","按关键信息、判断依据与可执行建议组织内容，便于快速阅读。","对不确定的信息明确标注，并给出下一步核验方式。"]}'),('image','{"prompts":[{"label":"未来都市","prompt":"生成一张未来城市夜景海报：雨后的高空视角，玻璃摩天楼与空中轨道层层延伸，霓虹蓝紫灯光倒映在湿润街道，远处有飞行器穿过薄雾，电影级广角构图，体积光，自然景深，画面层次丰富，细节清晰，8K 商业海报质感。"},{"label":"科技主视觉","prompt":"设计一张极简科技产品主视觉：银白色智能终端悬浮在纯净渐变空间中，柔和侧光勾勒金属边缘，少量蓝色光带表现数据流动，大面积留白，居中构图，高端发布会视觉风格，真实材质、精细阴影和清晰产品轮廓。"},{"label":"水墨山水","prompt":"绘制一幅水墨风格山水插画：层叠远山隐入晨雾，一叶木舟划过平静江面，岸边松树与古亭若隐若现，传统宣纸肌理，浓淡墨色自然晕染，局部淡青设色，构图疏密有致，留白克制，呈现宋代山水画的宁静意境。"},{"label":"美食广告","prompt":"创作一张高端中式餐饮广告：深色石材桌面上摆放一碗热气升腾的牛肉面，汤汁油亮，牛肉纹理和香菜细节清晰，暖金色侧逆光穿过蒸汽，背景虚化并保留标题留白，近景商业摄影，真实食物质感，诱人但不过度饱和。"},{"label":"角色设定","prompt":"绘制一张东方幻想角色设定图：年轻女性游侠身穿深青与银灰相间的轻甲，腰间佩剑，衣料、金属和皮革材质清晰；画面同时展示正面全身、侧面轮廓和面部特写，浅灰纯色背景，专业游戏概念设计稿，比例准确，细节统一。"}]}','{"asset":"/moma_5.12.0_estack/assets/forthBg-982e3d97.png"}'),('video','{"prompts":[{"label":"云海日出","prompt":"清晨云海之上，镜头从贴近云层的低空缓慢抬升，金色日光穿透薄雾照亮连绵山峰，云层随风流动，远处飞鸟掠过画面，电影级航拍，体积光，自然景深，色彩由冷蓝渐变为暖金，镜头运动平稳连贯。"},{"label":"产品环绕","prompt":"极简黑色智能终端置于深色展台中央，镜头沿顺时针方向缓慢环绕一周，冷白轮廓光扫过金属边缘，屏幕逐渐点亮并出现蓝色数据流，背景保持干净，商业广告质感，材质真实，动作稳定，产品始终位于画面视觉中心。"},{"label":"城市延时","prompt":"雨后城市夜景延时摄影，高楼灯光依次亮起，车流在湿润街道形成红蓝光轨，云层快速掠过天空，镜头固定在高处广角机位，画面从蓝调时刻自然过渡到深夜，曝光平滑，建筑结构稳定，呈现真实电影摄影质感。"},{"label":"人物漫步","prompt":"一名穿米色风衣的年轻人沿秋日林荫道向镜头缓慢走来，微风吹动衣摆与落叶，镜头以中景稳定后退跟拍，午后柔光从树隙洒下，肤色自然，背景有浅景深和轻微散景，动作连贯真实，电影叙事感。"},{"label":"微距花开","prompt":"一朵白色百合从花苞缓慢绽放的微距延时镜头，露珠沿花瓣滑落，清晨阳光从侧后方逐渐增强，背景为柔和绿色散景，镜头固定且焦点稳定，花瓣运动自然连续，细节锐利，真实生态纪录片质感。"}],"video":{"modes":["文生视频"],"resolutions":["1080P","720P"],"aspects":["16:9","9:16"],"durations":["5秒","10秒"],"accept":"image/*","add":"添加参考图片","sound":false}}','{"asset":"/moma_5.12.0_estack/assets/secondBg-c502c3d3.png"}'),('voice','{"voices":[{"id":"longxiaochun_v2","name":"龙小淳","desc":"温柔知性女声","icon":1},{"id":"longcheng_v2","name":"龙橙","desc":"沉稳磁性男声","icon":2},{"id":"longhua_v2","name":"龙华","desc":"新闻主播音色","icon":3},{"id":"longshu_v2","name":"龙书","desc":"自然叙事男声","icon":4},{"id":"longxiaobai_v2","name":"龙小白","desc":"活泼元气女声","icon":5},{"id":"longan_v2","name":"龙安","desc":"专业客服女声","icon":6},{"id":"longyue_v2","name":"龙悦","desc":"清新甜美女声","icon":1},{"id":"longlao_v2","name":"龙老","desc":"浑厚评书男声","icon":2}]}','{"answer":"大家好，今天我们讨论项目进度。请各位先介绍当前任务的完成情况，再确认下一阶段的工作安排。"}');
UPDATE db_state SET schema_version=16 WHERE id=1;
